// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a refusal (400) from a conflict with someone else's save (409). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { asString, useSearchParam } from '../../url/useSearchParam';

// The session lives in the URL: `user` is the signed-in name, `sheet` the active sheet id. Each
// browser keeps its own, so two users on one sheet act independently.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

/** The query key under which everything kept per sheet lives; re-loading a sheet invalidates it. */
export const sheetKey = (sheet: string) => ['sheet', sheet] as const;

/** A sheet as the store holds it: its id, its own "today" (yyyy-MM-dd) and whether it is archived. */
export type SheetInfo = { id: string; today: string; archived: boolean };

/** The query key for the sheet itself; under sheetKey, so re-loading the sheet re-reads it. */
export const sheetInfoKey = (sheet: string) => [...sheetKey(sheet), 'info'] as const;
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetInfoKey, useCurrentSheet } from './session';
import type { SheetInfo } from './session';

/**
