            case "NUMERIC", "DECIMAL" -> type + "(" + rs.getInt("NUMERIC_PRECISION") + ", " + rs.getInt("NUMERIC_SCALE")
                    + ")";
            case "CHARACTER VARYING" -> "VARCHAR(" + rs.getLong("CHARACTER_MAXIMUM_LENGTH") + ")";
            default -> type;
        };
    }

    private static String q(String name) {
        return "\"" + name + "\"";
    }
